from __future__ import annotations

from pathlib import Path

PKG_BUILDER = Path("src/LibProsperoPkg/PKG/ProsperoPkgBuilder.cs")
HIGH_LEVEL_BUILDER = Path("src/LibProsperoPkg/ProsperoPackageBuilder.cs")

_USING_MARKER = "using System.Linq;\nusing System.Text;\n"
_USING_PATCHED = "using System.Linq;\nusing System.Security.Cryptography;\nusing System.Text;\n"

_LOW_LEVEL_PROP_MARKER = """    /// <summary>The volume timestamp written into the PFS inode table.</summary>\n    public DateTime TimeStamp { get; init; } = DateTime.UnixEpoch;\n"""
_LOW_LEVEL_PROP_PATCHED = """    /// <summary>The volume timestamp written into the PFS inode table.</summary>\n    public DateTime TimeStamp { get; init; } = DateTime.UnixEpoch;\n\n    /// <summary>Package-image profile. Standard matches the normal Publishing Tools path; Nwonly is legacy/A-B only.</summary>\n    public LibProsperoPkg.ProsperoPackageImageProfile ImageProfile { get; init; } = LibProsperoPkg.ProsperoPackageImageProfile.Standard;\n"""

_BUILD_IMAGE_MARKER = """        // Builds (and writes to outputPath) one complete package.\n        void BuildImageOnce()\n        {\n            log(\"Preparing PS5 inner image (data-first)...\");\n"""
_BUILD_IMAGE_PATCHED = """        // Standard Publishing Tools path. Unlike nwonly this uses the conventional signed/encrypted\n        // outer PFS generated by ProsperoPfsBuilder. Its block and superblock integrity values are the\n        // HMAC-SHA256 values derived from EKPFS/seed that the conventional PFS reader verifies. The nested\n        // image is a normal superblock-first PFS compressed as PFSC; no naps_pkg_layout.dat or nwonly FIH\n        // counters are synthesized.\n        void BuildStandardImageOnce()\n        {\n            log(\"Preparing PS5 inner image (standard PFS)...\");\n            var innerRoot = BuildInnerTree(sourceFolder, props.Passcode);\n            string work = Path.Combine(Path.GetTempPath(), \"libprospero-standard-\" + Guid.NewGuid().ToString(\"N\"));\n            Directory.CreateDirectory(work);\n            string innerPlainPath = Path.Combine(work, \"inner.pfs\");\n            string innerPfscPath = Path.Combine(work, \"pfs_image.dat\");\n            string outerPath = Path.Combine(work, \"outer.pfs\");\n            try\n            {\n                var innerProps = new ProsperoPfsProperties\n                {\n                    root = innerRoot,\n                    FileTime = fileTime,\n                    BlockSize = BlockSize,\n                    Version = ProsperoPfsHeader.VersionPs5,\n                    Encrypt = false,\n                    Sign = false,\n                };\n                var innerBuilder = new ProsperoPfsBuilder(innerProps, log);\n                using (var inner = new FileStream(innerPlainPath, FileMode.Create, FileAccess.ReadWrite, FileShare.None))\n                {\n                    inner.SetLength(innerBuilder.CalculatePfsSize());\n                    innerBuilder.WriteImage(inner);\n                }\n                long innerPlainSize = new FileInfo(innerPlainPath).Length;\n                byte[] innerDigest;\n                using (var innerForDigest = File.OpenRead(innerPlainPath))\n                    innerDigest = SHA3_256.HashData(innerForDigest);\n\n                log(\"Compressing standard nested PFS (PFSC)...\");\n                ProsperoPfsc.PackFile(\n                    innerPlainPath, innerPfscPath,\n                    new ProsperoPfscOptions { BlockSize = BlockSize }, log);\n\n                var outerRoot = new ProsperoFsDir();\n                var nested = new ProsperoFsFile(innerPfscPath) { name = \"pfs_image.dat\", Parent = outerRoot };\n                outerRoot.Files.Add(nested);\n                byte[] outerSeed = RandomNumberGenerator.GetBytes(16);\n                var outerProps = new ProsperoPfsProperties\n                {\n                    root = outerRoot,\n                    FileTime = fileTime,\n                    BlockSize = BlockSize,\n                    Version = ProsperoPfsHeader.VersionPs5,\n                    Encrypt = true,\n                    Sign = true,\n                    EKPFS = ekpfs,\n                    Seed = outerSeed,\n                };\n                var outerBuilder = new ProsperoPfsBuilder(outerProps, log)\n                {\n                    CaptureImageDigests = true,\n                    CaptureSuperblockIcv = true,\n                };\n                long pfsSize = outerBuilder.CalculatePfsSize();\n                int imagedigsSize = checked((int)(pfsSize / BlockSize * 32));\n                long nestedStoredSize = new FileInfo(innerPfscPath).Length;\n                long innerAlignedSize = (nestedStoredSize + BlockSize - 1) / BlockSize * BlockSize;\n                long mchunkTotal = (long)ProsperoImageDigests.FihRelativeImageOffset + pfsSize;\n                long mchunk0 = Math.Min(Math.Max(BlockSize, innerAlignedSize), Math.Max(BlockSize, mchunkTotal - BlockSize));\n                long mchunk1 = mchunkTotal - mchunk0;\n                uint playgoFileCount = checked((uint)innerRoot.GetAllChildrenFiles().Count);\n\n                var pkg = BuildContainer(\n                    props, ekpfs, sourceFolder, (ulong)pfsSize, imagedigsSize, playgoFileCount,\n                    (ulong)mchunk0, (ulong)mchunk1);\n                var imagedigsEntry = (ProsperoCntGenericEntry)pkg.Entries.First(e => (uint)e.Id == ImagedigsEntryId);\n\n                using (var outer = new FileStream(outerPath, FileMode.Create, FileAccess.ReadWrite, FileShare.None))\n                {\n                    outer.SetLength(pfsSize);\n                    outerBuilder.WriteImage(outer);\n                }\n                if (outerBuilder.ImageDigests is not { Length: > 0 } || outerBuilder.ImageDigests.Length != imagedigsEntry.FileData.Length)\n                    throw new InvalidDataException(\"Standard outer PFS did not produce the expected imagedigs.dat table.\");\n                // ProsperoPfsBuilder captures conventional imagedigs in their on-disk byte order.\n                imagedigsEntry.FileData = (byte[])outerBuilder.ImageDigests.Clone();\n\n                long totalSize = (long)(pkg.Header.body_offset + pkg.Header.body_size + pkg.Header.pfs_image_size);\n                using (var fs = new FileStream(outputPath, FileMode.Create, FileAccess.ReadWrite, FileShare.None))\n                {\n                    fs.SetLength(totalSize);\n                    fs.Position = (long)pkg.Header.pfs_image_offset;\n                    using (var outer = File.OpenRead(outerPath))\n                        outer.CopyTo(fs);\n\n                    ProsperoPfsImageXmlOptions siXml = FinishContainer(\n                        pkg, fs, props, innerDigest, 0, 0, null, log);\n                    siXml.OuterPfsTree = outerBuilder.CaptureImageTree();\n                    siXml.ChunkInfo = new ProsperoChunkInfoModel\n                    {\n                        PlayGoChunkDatSize = (pkg.Entries.FirstOrDefault(e => (uint)e.Id == PlayGoChunkDatEntryId) as ProsperoCntGenericEntry)?.FileData.Length ?? 0,\n                        TotalSize = mchunkTotal,\n                        Outer0Size = mchunk0,\n                        Outer1Size = mchunk1,\n                    };\n                }\n\n                capturedNestedDigest = innerDigest;\n                // 0xA8 and the nwonly FIH counters describe naps_pkg_layout.dat and must stay clear\n                // for the standard superblock-first/PFSC profile.\n                capturedNestedImageSize = 0;\n                capturedNestedMetaBaseBlocks = 0;\n                capturedNwonlyFih = null;\n                capturedSi = null;\n                log($\"Standard profile: conventional signed outer PFS, nested plain={innerPlainSize:N0}, PFSC={nestedStoredSize:N0}.\");\n            }\n            finally\n            {\n                try { Directory.Delete(work, recursive: true); } catch { }\n            }\n        }\n\n        // Builds (and writes to outputPath) one complete package.\n        void BuildImageOnce()\n        {\n            if (props.ImageProfile == LibProsperoPkg.ProsperoPackageImageProfile.Standard)\n            {\n                BuildStandardImageOnce();\n                return;\n            }\n\n            log(\"Preparing PS5 inner image (legacy nwonly/data-first)...\");\n"""

_HIGH_ENUM_MARKER = """/// <summary>Options describing the PS5 package to build.</summary>\npublic sealed class ProsperoBuildOptions\n"""
_HIGH_ENUM_PATCHED = """/// <summary>Package image profile. Standard follows normal Publishing Tools creation; Nwonly is legacy/A-B only.</summary>\npublic enum ProsperoPackageImageProfile\n{\n    Standard,\n    Nwonly,\n}\n\n/// <summary>Options describing the PS5 package to build.</summary>\npublic sealed class ProsperoBuildOptions\n"""

_HIGH_PROP_MARKER = """    public ProsperoOutputFormat OutputFormat { get; set; } = ProsperoOutputFormat.DebugImage;\n\n    /// <summary>Folder whose contents become the package image (must contain <c>sce_sys/</c>).</summary>\n"""
_HIGH_PROP_PATCHED = """    public ProsperoOutputFormat OutputFormat { get; set; } = ProsperoOutputFormat.DebugImage;\n\n    /// <summary>Image layout profile. Standard is the default; Nwonly is retained only for diagnostics/A-B.</summary>\n    public ProsperoPackageImageProfile ImageProfile { get; set; } = ProsperoPackageImageProfile.Standard;\n\n    /// <summary>Folder whose contents become the package image (must contain <c>sce_sys/</c>).</summary>\n"""

_BUILD_PROPS_MARKER = """            VolumeType = ProsperoVolumeTypeForMode(options.Mode),\n        };\n"""
_BUILD_PROPS_PATCHED = """            VolumeType = ProsperoVolumeTypeForMode(options.Mode),\n            ImageProfile = options.ImageProfile,\n        };\n"""


def _replace(path: Path, old: str, new: str, label: str) -> bool:
    if not path.is_file():
        raise RuntimeError(f"LibProsperoPKG {label} is missing: {path}")
    text = path.read_text(encoding="utf-8")
    if new in text:
        return False
    if old not in text:
        raise RuntimeError(
            f"Pinned LibProsperoPKG {label} no longer matches the standard-profile preimage; "
            "review the pinned engine before updating it."
        )
    path.write_text(text.replace(old, new, 1), encoding="utf-8")
    return True


def apply_standard_package_profile(vendor_dir: str | Path) -> bool:
    vendor = Path(vendor_dir)
    low = vendor / PKG_BUILDER
    high = vendor / HIGH_LEVEL_BUILDER
    changed = False
    changed |= _replace(low, _USING_MARKER, _USING_PATCHED, "standard profile crypto import")
    changed |= _replace(low, _LOW_LEVEL_PROP_MARKER, _LOW_LEVEL_PROP_PATCHED, "standard profile property")
    changed |= _replace(low, _BUILD_IMAGE_MARKER, _BUILD_IMAGE_PATCHED, "standard image builder")
    changed |= _replace(high, _HIGH_ENUM_MARKER, _HIGH_ENUM_PATCHED, "standard profile enum")
    changed |= _replace(high, _HIGH_PROP_MARKER, _HIGH_PROP_PATCHED, "standard profile option")
    changed |= _replace(high, _BUILD_PROPS_MARKER, _BUILD_PROPS_PATCHED, "standard profile propagation")
    return changed
